import React, { useEffect } from "react";
import { useNavigate } from "react-router-dom";

const SplashScreen = () => {
  const navigate = useNavigate();

  useEffect(() => {
    setTimeout(() => {
      navigate("/");
    }, 12000); // ⏱️ 12 sec
  }, []);

  return (
    <div style={styles.container}>

      <div style={styles.card}>
        <h1 style={styles.title}>🎓 EduSaarthi</h1>

<p style={styles.subtitle}>
  AI-Powered Academic Companion
</p>

<p style={styles.desc}>
  A next-generation learning platform built for modern university students.  
  Seamlessly access study resources, stay updated with institutional notices,  
  and interact with an intelligent chatbot for instant academic support.
</p>

        <div style={styles.loader}></div>

        <p style={styles.loading}>Loading your experience...</p>
      </div>

    </div>
  );
};

export default SplashScreen;


// 🎨 STYLE
const styles = {
  container: {
    height: "100vh",
    background: "linear-gradient(135deg, #0f172a, #1e293b)",
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    color: "white",
  },
  card: {
    textAlign: "center",
    padding: "40px",
    borderRadius: "12px",
    background: "#1e293b",
    boxShadow: "0 0 30px rgba(0,0,0,0.5)",
    maxWidth: "400px",
  },
  title: {
    fontSize: "32px",
    marginBottom: "10px",
    color: "#38bdf8",
  },
  subtitle: {
    fontSize: "18px",
    marginBottom: "10px",
    color: "#22c55e",
  },
  desc: {
    fontSize: "14px",
    marginBottom: "20px",
    color: "#cbd5f5",
  },
  loading: {
    marginTop: "10px",
    fontSize: "13px",
    color: "#94a3b8",
  },
  loader: {
    border: "4px solid #334155",
    borderTop: "4px solid #38bdf8",
    borderRadius: "50%",
    width: "40px",
    height: "40px",
    margin: "auto",
    animation: "spin 1s linear infinite",
  },
};
